    pub fn normalize(&self, host: &str, model: &str) -> String {
        match self.host(host).map(|entry| entry.id_style) {
            Some(ModelIdStyle::BareId) => model
                .split_once('/')
                .map(|(_, rest)| rest)
                .unwrap_or(model)
                .to_owned(),
            Some(ModelIdStyle::ProviderModel) | None => model.to_owned(),
        }
    }
}

