 use super::parse_claude_json;

 #[test]
 fn parse_claude_json_extracts_result_and_tokens() {
 let raw = r#"{
 "type": "result",
 "subtype": "success",
 "is_error": false,
 "result": "Hello, world!",
 "session_id": "abc",
 "num_turns": 1,
 "total_cost_usd": 0.001,
 "usage": {
 "input_tokens": 42,
 "output_tokens": 7,
 "cache_read_input_tokens": 0,
 "cache_creation_input_tokens": 0
 }
 }"#;
 let (text, tokens_in, tokens_out) = parse_claude_json(raw);
