10	pub fn config_hash(path: &Path) -> Result<String, RunError> {
11	    let bytes = std::fs::read(path).map_err(|source| RunError::Io {
12	        path: path.to_path_buf(),
13	        source,
14	    })?;
15	    let yaml: serde_yaml::Value = serde_yaml::from_slice(&bytes).map_err(|source| {
16	        RunError::Config(format!(
17	            "failed to canonicalise {}: {source}",
18	            path.display()
19	        ))
20	    })?;
21	    let canonical = serde_json::to_vec(&canonical_json(yaml)).map_err(|source| RunError::Json {
22	        path: path.to_path_buf(),
23	        source,
24	    })?;
25	    let digest = Sha256::digest(canonical);
26	    Ok(format!("sha256:{}", hex_lower(&digest)))
27	}
